from pathlib import Path
import json,csv
out=Path(__file__).resolve().parent
cards=[]
def add(title,kind,actors,ids,mechanism,benefit,rival,existing,differentiation,tradeoff,gp,kill):
 cards.append(dict(option_id=f'OPT-C{len(cards)+1:02}',title=title,option_class=kind,affected_stakeholders=actors,evidence_ids=ids,status='candidate direction for user assessment; not a selected recommendation',mechanism=mechanism,proposed_benefit=benefit,benefit_status='hypothesized; not measured',strongest_rival=rival,existing_similar_feature=existing,differentiation_and_transfer_limit=differentiation,stakeholder_tradeoff=tradeoff,conditional_gp_mechanism=gp,cost_status='Unknown; no budget or ROI estimate',kill_condition=kill,auto2000_gap_status='Not established by this competitor workstream; requires root evidence integration',implementation_status='No implementation design or roadmap'))
add('Explain the distinct roles of ecosystem apps','information and role clarity',['customer','Toyota OEM','digital owner'],['COMP-001','COMP-002','COMP-007'],'Clarify which existing route owns a customer task and what information it can reliably show.','Reduce choosing the wrong route or repeating a search.','Users already understand the roles; low activity reflects infrequent need.','mToyota advertises ownership and purchase functions; SEVA supplies finance routes.','Value would be role clarity, not a new version of an existing feature; app integration remains unknown.','Central consistency versus dealer-specific propositions.','Only useful if more eligible opportunities are retained or realizable servicing effort falls.','Current users find the right existing route without consequential uncertainty.')
add('Preserve a customer task summary into human assistance','cross-channel continuity',['customer','adviser','CRM owner'],['COMP-010','COMP-013','COMP-038'],'Make the unresolved question, prior information and decision stage clear at a handoff.','Reduce re-explanation and inconsistent expectations.','Qualification and physical verification require fresh information regardless of earlier digital activity.','SEVA partner handoff; OLXmobbi inspection; Honda dealer confirmation.','Potential context continuity, not assumed system interoperability or permission to share all data.','Adviser usefulness versus collection and privacy burden.','Additional fulfilled contribution or economically realizable adviser-time savings.','Actual handoffs already retain context or summary adds no consequential value.')
add('Distinguish requested, reviewed and confirmed booking states','service decision transparency',['owner','service adviser','branch manager'],['COMP-019','COMP-020','COMP-038'],'Explain the difference between a requested time and an accepted appointment.','Make the customer expectation match the represented process.','Customers understand the current states and confirmations are timely.','Honda guide explicitly uses awaiting confirmation; Astrido publishes booking lead time.','State clarity may transfer; actual capacity cannot be inferred from an interface.','Fast-looking conversion versus honest appointment commitment.','Could retain eligible completed jobs or reduce wasted contacts; uplift unknown.','No current Auto2000 state confusion or material consequence is found.')
add('Show task-specific preparation before a visit','customer preparation',['owner','appraiser','service adviser'],['COMP-013','COMP-014','COMP-020'],'Explain required documents, vehicle checks and arrival requirements for the chosen task.','Reduce unproductive visits or appraisal delays.','Customers receive adequate advice through existing channels.','OLXmobbi document/inspection process and Astrido appointment terms.','Preparation should be scoped to the actual job; unnecessary document requests must not be inferred.','Upfront clarity versus overload at early consideration.','More completed eligible work per visit or lower repeat-handling cost.','Missing preparation is rare or later reminders solve it adequately.')
add('Explain coverage eligibility for the actual vehicle cohort','ownership information',['owner','OEM','service adviser'],['COMP-003','COMP-004','COMP-026','COMP-027'],'Distinguish included work, warranty scope, age/mileage limits and continuation conditions.','Support an accurate ownership decision at the relevant moment.','Owners understand the terms or do not need more detail.','Toyota T-Care/XTRA and Hyundai battery/vehicle distinctions.','No universal entitlement should be promised; exact vehicle contract governs.','Simple message versus accurate exceptions.','May improve capture of eligible work; existing demand may simply migrate channels.','Terms are already clear and no consequential uncertainty appears.')
add('Clarify what changes when ownership transfers','resale information',['used buyer','seller','appraiser'],['COMP-013','COMP-034','COMP-036'],'Separate original-owner campaign benefits from protections available to a subsequent owner.','Prevent mistaken comparisons of used-vehicle protection.','Transfer terms are already disclosed and buyers are primarily price constrained.','Historical Wuling/Chery first-owner or campaign conditions; OLXmobbi actual appraisal.','Current contracts must be verified; historical offers cannot diagnose current entitlements.','Resale reassurance versus honest disclosure of lost benefits.','Only if information changes a viable retained trade-in or sale, net of verification cost.','No relevant transfer restriction applies or buyers already understand it.')
add('Separate fleet use from private-use benefit comparisons','fleet decision support',['fleet buyer','procurement','finance partner'],['COMP-034','COMP-036'],'Keep commercial-use eligibility explicit when comparing ownership propositions.','Avoid using a retail warranty headline in a fleet decision.','Fleet procurement already receives correct contract-specific advice.','Selected historical lifetime campaigns exclude commercial use.','Not evidence that Auto2000 lacks a fleet route or that all rival programmes exclude fleets.','Retail simplicity versus contract-specific fleet information.','Potential qualified fleet opportunity value; actual account contribution unknown.','No fleet eligibility mismatch or reachable fleet demand exists.')
add('Explain the meaning and limits of battery-check results','health evidence comprehension',['owner','warranty adviser','OEM'],['COMP-005','COMP-006'],'Distinguish check date/result, eligibility and the separate warranty validation decision.','Reduce false reassurance or mistaken expectation of automatic replacement.','Existing certificate and adviser explanations are sufficient.','Toyota already issues eligible health certificates and validates adverse results.','This is an explanation opportunity, not a claim that battery checking is new.','Customer reassurance versus technical/contractual precision.','Could support captured eligible work; no certificate-to-GP effect is measured.','Users correctly interpret certificates and no material confusion appears.')
add('Connect verified ownership evidence to appraisal questions','transaction evidence',['seller','buyer','appraiser','OEM'],['COMP-005','COMP-013','COMP-014'],'Use valid dated health/history evidence to answer relevant appraisal uncertainty without promising residual value.','Make an inspection conversation better informed.','Physical inspection and market demand dominate valuation; prior records add no value.','Toyota certificate and OLXmobbi physical appraisal already exist separately.','Partner acceptance and transferable evidence rights are unknown; no resale uplift may be assumed.','Seller convenience versus appraisal independence and liability.','Additional retained trade-ins/deliveries or appraisal effort savings, conditional on partner use.','Appraisers do not use the evidence or it adds no decision value.')
add('Make indicative and inspected trade-in values visibly different','valuation transparency',['seller','appraiser','sales adviser'],['COMP-012','COMP-013'],'Explain when and why the initial estimate can change and when a sale is agreed.','Set accurate expectations before committing time or a new-car purchase.','Current users already understand the estimate is nonbinding.','OLXmobbi explicitly distinguishes indicative and actual valuation.','No binding price or guaranteed purchase should be invented.','Early certainty appeal versus honest condition risk.','Potential fewer lost viable trade-ins; margin and volume effect unknown.','No consequential misunderstanding or alternative wording is needed.')
add('Clarify when transaction timing starts','transaction transparency',['seller','customer service','payment partner'],['COMP-012','COMP-013','COMP-014'],'State which prerequisites precede an advertised payment or completion time.','Prevent interpreting a conditional time promise from the first digital action.','The current promise is clear and customers ask no timing questions.','OLXmobbi times payment after deal and complete documents.','Do not copy the timing unless the responsible provider guarantees it for the actual transaction.','Compelling headline versus qualified, accurate promise.','Could reduce rework and retain viable transactions; no time-based causal uplift measured.','No current expectation mismatch appears.')
add('Explain prequalification validity and decision authority','finance information',['buyer','lender','sales adviser'],['COMP-007','COMP-009','COMP-010'],'Distinguish simulation, credit-opportunity check, partner decision and expiry.','Help buyers know which uncertainty is resolved and which remains.','The main obstacle is true affordability or creditworthiness.','SEVA already offers these routes and partner/expiry terms.','No approval guarantee or lender model should be implied.','Fast progress signal versus accurate financial status.','More eligible financed deliveries or less repeated handling; no acceptance uplift assumed.','Users already understand status or offer economics dominate.')
add('Explain household inputs needed for a finance decision','household decision support',['applicant','spouse/payer','lender','privacy owner'],['COMP-010'],'Explain the purpose and decision stage of required household information.','Support informed preparation without collecting unnecessary sensitive data.','Existing lender communication already supplies sufficient context.','SEVA terms mention spouse KTP for married applicants.','Does not justify sharing documents through an unapproved app or infer household coordination pain.','Application completeness versus sensitive-data burden.','Fewer avoidable incomplete eligible applications; actual frequency/cost unknown.','No material household-information confusion or incomplete demand is found.')
add('Explain parts compatibility and warranty conditions together','parts information',['owner','parts adviser','warranty owner'],['COMP-025','COMP-034'],'Clarify fit, original-part requirements and the applicable coverage boundary for an actual job.','Help users assess an appropriate part/service offer.','Price and stock dominate; compatibility is already clear.','BYD and historical Wuling terms reference original parts.','No claim that every aftermarket part voids all coverage; exact causal/contract terms govern.','Accessible choice information versus overbroad warranty claims.','Captured suitable parts jobs net of returns/rework; unknown realized margin.','No compatibility uncertainty or benefit from extra explanation exists.')
add('Compare ownership cost with service entitlements included','decision support',['shopper','owner','finance director'],['COMP-003','COMP-004','COMP-011','COMP-027'],'Distinguish paid work from included labour/parts/coverage when comparing ownership options.','Avoid counting benefits or costs twice.','Upfront affordability, vehicle fit or stock decides the choice.','Toyota service programmes, OLXmobbi benefits and priced Hyundai extension.','Requires comparable model, usage, offer date, tax and warranty scope; no generic cost-saving percentage.','Helpful comparison versus false precision.','Incremental suitable deliveries only; no assumed conversion effect from a calculator.','Reliable comparable inputs are absent or comparison does not affect viable choices.')
add('Explain a paid protection extension as a separate choice','commercial comparison',['owner','CFO','OEM warranty team'],['COMP-004','COMP-028'],'Compare coverage continuation conditions and a priced extension without equating them.','Help users understand a protection decision and its cost.','Eligible owners do not value extra cover or already receive adequate advice.','Toyota conditional XTRA versus Hyundai published IONIQ5 extension.','Different models/contracts; Hyundai price is not Auto2000 cost or willingness to pay.','Customer certainty versus exclusion and price disclosure.','Potential incremental net programme contribution, but provider split and cost are unknown.','No unmet decision or feasible control over the offered product exists.')
add('Match specialist repair needs to a suitable branch','task-specific discovery',['owner','B&P team','branch manager'],['COMP-018','COMP-019'],'Make general repair, B&P and home service capability distinctions relevant to the customer job.','Reduce wrong-route inquiries.','Existing branch selection and adviser referral work well.','Tunas separate B&P tab and Astrido workshop/home choices.','No actual Auto2000 misrouting or branch capacity is established.','Customer simplicity versus local capability detail.','Additional completed suitable jobs or reduced reassignment effort.','No material wrong routing exists or capability information is unreliable.')
add('Explain emergency support by service and locality','local eligibility information',['driver','field team','customer care'],['COMP-030','COMP-031','COMP-033','COMP-040'],'Distinguish phone access, technician dispatch, charging, towing and geographic charges.','Help drivers understand usable help under actual conditions.','People need a simple reliable contact rather than detailed comparison.','Hyundai, Wuling and Honda publish different radii and hours.','A benchmark cannot create Auto2000 field supply or a 24h guarantee.','Reassurance and simplicity versus geographically qualified promises.','Retention or realizable handling savings plausible; emergency GP may be zero or negative.','Current help reliably resolves the job and extra detail adds burden.')
add('Explain onward-mobility support during a qualifying repair','ownership support information',['driver','household','service partner'],['COMP-030','COMP-031'],'Clarify whether and when a qualifying breakdown includes onward transport.','Support the travel consequence of a vehicle fault.','Users already have insurer/ride-hail alternatives or demand is small.','Hyundai publishes a conditional GrabCar route after emergency towing.','Not proof Auto2000 controls an equivalent service or that free transport pays back.','Customer relief versus subsidy and partner liability.','Only a conditional retention or cost-to-serve link; no margin assumption.','Existing alternatives suffice or attributable benefit cannot cover cost.')
add('Make home-service suitability visible before choosing it','service qualification',['owner','mobile technician','branch'],['COMP-019','COMP-032','COMP-033'],'Explain which task/location is suitable for home service versus workshop work.','Avoid selecting a convenient but ineligible service route.','Current booking logic already handles suitability well.','Astrido home/office and Wuling mobile/home service distinctions.','Actual skills, scope and capacity need reliable current owner data.','Convenience versus diagnosis and safety constraints.','Additional suitable captured work minus travel and displaced technician time.','No unsuitable selections or economically viable unserved needs appear.')
add('Explain connected-account setup and ownership changes','connected-access information',['owner','dealer','OEM','privacy owner'],['COMP-023','COMP-024','COMP-029'],'Explain the role of dealer verification, vehicle compatibility and account access at setup/transfer.','Help owners understand next steps when functions are unavailable.','OEM enrollment already works adequately and the dealer adds no value.','BYD dealer-assisted linking; Hyundai separate connected contract.','Dealer cannot promise remote access outside OEM permissions or compatibility.','Speed and convenience versus account/vehicle security.','Potential fewer support contacts or retained service relationship; effect unknown.','No unresolved setup task or permissible dealer role exists.')
add('Make connected-service renewal terms understandable','digital contract information',['owner','OEM','digital business owner'],['COMP-029'],'Explain free-period expiry and optional renewal separately from warranty.','Prevent mistaking vehicle protection for perpetual connected access.','Users know the distinction and renew only when they value the service.','Hyundai Bluelink has a three-year free period and separate service contract.','No current renewal price, dealer revenue share or conversion evidence exists.','Useful ongoing service versus subscription cost and expectations.','Possible partner service contribution only if permitted and truly incremental.','No relevant contractual confusion or Auto2000 role exists.')
add('Assess multi-vehicle and multi-user needs separately','audience differentiation',['household','fleet admin','driver','OEM'],['COMP-024','COMP-010'],'Distinguish owning several vehicles from concurrent access by different responsible people.','Identify a precise audience requirement before treating all owners alike.','Most relevant users need only one device and one vehicle.','BYD states up to ten vehicles with no concurrent multi-phone account use.','Not permission to share credentials or change OEM security; no unmet Auto2000 requirement is proven.','Role convenience versus security and privacy accountability.','Potential qualified fleet/household retention; no audience size or GP measured.','No consequential multi-role need is found.')
add('Explain service-dependent benefit continuity','ownership decision information',['owner','service adviser','OEM'],['COMP-004','COMP-025','COMP-027','COMP-034'],'Make the relationship between scheduled upkeep and applicable benefits clear at the relevant job.','Help owners make informed official-service choices.','Customers already know conditions; provider choice is driven by price or location.','Multiple operators publish authorized-maintenance conditions.','Do not imply skipped service automatically removes every warranty right; exact terms govern.','Benefit clarity versus fear-based retention claims.','Possible captured eligible work; not proof of added jobs due.','No confusion or attributable difference in provider choice appears.')
add('Separate enduring benefits from expired campaign bundles','content governance',['shopper','publisher','commercial owner'],['COMP-034','COMP-035','COMP-036','COMP-037'],'Keep offer date, model/variant and limited buyer cohort explicit in comparisons.','Reduce reliance on an attractive but inapplicable historical benefit.','Current pages already label campaign scope clearly and customers verify with advisers.','Wuling pre-book and Chery early-buyer announcements show bounded offers.','Historical search visibility is not itself misleading current advertising or proven harm.','Commercial message reach versus consistent current terms.','Fewer unsuitable inquiries or lost viable decisions; no quantified revenue loss.','Current content and advisers already resolve the distinction without consequential friction.')
(out/'option_cards.json').write_text(json.dumps(cards,ensure_ascii=False,indent=2))
with (out/'option_cards.csv').open('w',newline='',encoding='utf8') as f:
 rows=[{**c,'affected_stakeholders':' | '.join(c['affected_stakeholders']),'evidence_ids':' | '.join(c['evidence_ids'])} for c in cards];w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
md=['# Candidate directions for user selection','\nThese 25 distinct cards are hypothesis-led options grounded in public competitor mechanisms. They do not establish an unmet Auto2000 need, adoption, impact or novelty. Each card must be linked to Auto2000 evidence and contrary cases before user assessment. No winner, implementation or roadmap is supplied. Counts refer to analytical options, not empirical observations.\n']
for c in cards:
 md += [f"## {c['option_id']}: {c['title']}",f"Evidence: {', '.join(c['evidence_ids'])}. Class: {c['option_class']}.",f"Mechanism: {c['mechanism']}",f"Benefit hypothesis: {c['proposed_benefit']}",f"Rival: {c['strongest_rival']}",f"Existing analogue: {c['existing_similar_feature']}",f"Transfer limit: {c['differentiation_and_transfer_limit']}",f"Stakeholder trade-off: {c['stakeholder_tradeoff']}",f"Economic link: {c['conditional_gp_mechanism']} Costs remain unknown.",f"Kill condition: {c['kill_condition']}\n"]
(out/'option_cards.md').write_text('\n\n'.join(md))
print('cards',len(cards))
